CustomField.formula:
IF(
    CONTAINS(Lower(TEXT(Shipping_Vendor__c)),"3rd"),"3`  `" +  Ship_Via__c + 
    if(AND(Total_Lines_Shipped_SUM__c < 1, Freight_Amount__c > 0),"` FC: $" + TEXT(Freight_Amount__c),""),
 if(
    CONTAINS(Lower(TEXT(Shipping_Vendor__c)),"col")," 2`  `" +  Ship_Via__c + 
    if(AND(Total_Lines_Shipped_SUM__c < 1, Freight_Amount__c > 0),"` FC: $" + TEXT(Freight_Amount__c),""),
    "1`  `" + if(AND(Total_Lines_Shipped_SUM__c < 1, Freight_Amount__c > 0),"` FC: $" + TEXT(Freight_Amount__c),"")
 )
)
